/**
 * Owns pure radiant-eclipse facts, knowledge shapes and their inert-data readers.
 * Inputs are original event identifiers and JSON.parse/no-reviver or proven
 * inert payloads; outputs preserve exact copied shapes, null rejection, limits
 * and visibility classifications. These facts never authorize actions or write
 * domain resources/state. Node ingress must reject hostile Proxy objects before
 * shared reflection; this browser-compatible module supplies no runtime handles.
 */
import { copyEventData } from "../inert-event-data";
export const RADIANT_ECLIPSE_EVENT_TYPES = Object.freeze([
  "eclipse_swallowed",
  "eclipse_native_suppressed",
  "eclipse_native_restored",
  "eclipse_lease_closed",
  "radiant_shelter_chosen",
] as const);
export type RadiantEclipseFact =
  | {
      actorId: number;
      day: number;
      targetId: number | null;
      roleId: "villager" | "seer" | "witch" | "dreamer" | "radiant_count" | null;
      abilityId: string | null;
    }
  | { playerId: number; day: number }
  | {
      actorId: number;
      day: number;
      targetId: number | null;
      abilityId: string | null;
      status: "committed" | "aborted";
    }
  | { actorId: number; day: number; targetId: number | null; abilityId: string };
function id(v: unknown): v is number {
  return typeof v === "number" && Number.isSafeInteger(v) && v > 0 && v < Number.MAX_SAFE_INTEGER;
}
function exact(p: Record<string, unknown>, keys: string[]) {
  return Object.keys(p).length === keys.length && keys.every((k) => Object.hasOwn(p, k));
}
export function readRadiantEclipseFact(type: string, value: unknown): RadiantEclipseFact | null {
  if (!(RADIANT_ECLIPSE_EVENT_TYPES as readonly string[]).includes(type)) return null;
  try {
    const copied = copyEventData(value);
    if (!copied || typeof copied !== "object" || Array.isArray(copied)) return null;
    const p = copied as Record<string, unknown>;
    if (!id(p.day)) return null;
    if (type === "eclipse_native_suppressed" || type === "eclipse_native_restored")
      return exact(p, ["playerId", "day"]) && p.day >= 2 && id(p.playerId)
        ? (p as unknown as RadiantEclipseFact)
        : null;
    if (!id(p.actorId) || (p.targetId !== null && !id(p.targetId))) return null;
    if (type === "eclipse_lease_closed")
      return exact(p, ["actorId", "day", "targetId", "abilityId", "status"]) &&
        ["committed", "aborted"].includes(p.status as string) &&
        p.targetId !== p.actorId &&
        (p.targetId !== null || p.abilityId === null) &&
        (p.day !== 1 || (p.targetId === null && p.abilityId === null)) &&
        (p.abilityId === null || p.abilityId === `copy:eclipse:night:${p.day}`)
        ? (p as unknown as RadiantEclipseFact)
        : null;
    if (p.day < 2) return null;
    if (type === "radiant_shelter_chosen")
      return exact(p, ["actorId", "day", "targetId", "abilityId"]) &&
        p.targetId !== p.actorId &&
        (p.abilityId === "native:shelter" || p.abilityId === `copy:eclipse:night:${p.day}`)
        ? (p as unknown as RadiantEclipseFact)
        : null;
    if (!exact(p, ["actorId", "day", "targetId", "roleId", "abilityId"])) return null;
    if (p.targetId === null)
      return p.roleId === null && p.abilityId === null
        ? (p as unknown as RadiantEclipseFact)
        : null;
    return p.targetId !== p.actorId &&
      ["villager", "seer", "witch", "dreamer", "radiant_count"].includes(p.roleId as string) &&
      (p.roleId === "villager"
        ? p.abilityId === null
        : p.abilityId === `copy:eclipse:night:${p.day}`)
      ? (p as unknown as RadiantEclipseFact)
      : null;
  } catch {
    return null;
  }
}
export function radiantEclipseAudience(type: string, fact: RadiantEclipseFact): readonly number[] {
  return type === "eclipse_lease_closed" ? [] : ["playerId" in fact ? fact.playerId : fact.actorId];
}

/**
 * Owns pure Wall Note text, event, item snapshot and tool contracts for wire consumers.
 * Inputs are identifiers and proven inert payload data; outputs are detached
 * shapes or null with original keys, limits, defaults and scalar correlations.
 * Text validity preserves the exact Unicode limit and user text; it does not
 * translate/render wording or grant the anonymous-note item capability.
 * For these inputs the reader never changes rules, resources, phases or action
 * authority. Proxy reflection safety belongs to Node ingress before calling;
 * browser consumers must supply inert data rather than arbitrary JS objects.
 */
import { copyEventData } from "../inert-event-data";
export const WALL_EVENT_TYPES = [
  "wall_notes_started",
  "wall_notes_published",
  "wall_notes_canceled",
  "wall_note_changed",
  "wall_note_order_recorded",
] as const;
export function validWallText(value: unknown): value is string {
  if (typeof value !== "string" || !value.trim() || Array.from(value).length > 160) return false;
  for (let i = 0; i < value.length; i++) {
    const c = value.charCodeAt(i);
    if (c >= 0xd800 && c <= 0xdbff) {
      const d = value.charCodeAt(++i);
      if (!(d >= 0xdc00 && d <= 0xdfff)) return false;
    } else if (c >= 0xdc00 && c <= 0xdfff) return false;
  }
  return true;
}
export function readWallTool(
  value: unknown,
): { name: "write_note"; args: { text: string } } | null {
  try {
    const c = copyEventData(value) as any;
    return c &&
      Object.keys(c).length === 2 &&
      c.name === "write_note" &&
      c.args &&
      Object.keys(c.args).length === 1 &&
      validWallText(c.args.text)
      ? { name: "write_note", args: { text: c.args.text } }
      : null;
  } catch {
    return null;
  }
}
export function readWallEventFact(type: string, value: unknown): Record<string, any> | null {
  if (!(WALL_EVENT_TYPES as readonly string[]).includes(type)) return null;
  try {
    const p = copyEventData(value) as any;
    const exact = (v: any, names: string[]) =>
      v &&
      !Array.isArray(v) &&
      typeof v === "object" &&
      Object.keys(v).length === names.length &&
      Object.keys(v).every((k) => names.includes(k));
    const id = (n: any) => Number.isSafeInteger(n) && n > 0;
    if (!p || p.day !== 1 || p.eventId !== "awa_wall_notes_v1") return null;
    if (type === "wall_notes_started") return exact(p, ["day", "eventId"]) ? p : null;
    if (type === "wall_notes_canceled")
      return exact(p, ["day", "eventId", "reason"]) && p.reason === "scope_changed" ? p : null;
    if (type === "wall_notes_published")
      return exact(p, ["day", "eventId", "texts"]) &&
        Array.isArray(p.texts) &&
        p.texts.every(validWallText)
        ? p
        : null;
    if (type === "wall_note_order_recorded") {
      if (!exact(p, ["day", "eventId", "rows"]) || !Array.isArray(p.rows)) return null;
      const authors = new Set();
      for (const [rank, row] of p.rows.entries()) {
        if (
          !exact(row, ["actorId", "instanceId", "text", "rank"]) ||
          !id(row.actorId) ||
          authors.has(row.actorId) ||
          row.instanceId !== `wall:1:${row.actorId}` ||
          row.rank !== rank ||
          !validWallText(row.text)
        )
          return null;
        authors.add(row.actorId);
      }
      return p;
    }
    const accepted = p.operation === "accepted";
    if (
      !exact(p, [
        "day",
        "eventId",
        "actorId",
        "itemId",
        "instanceId",
        "operation",
        "remaining",
        "expired",
        ...(accepted ? ["text"] : []),
      ]) ||
      !id(p.actorId) ||
      p.itemId !== "anonymous_note" ||
      p.instanceId !== `wall:1:${p.actorId}` ||
      ![0, 1].includes(p.remaining) ||
      typeof p.expired !== "boolean"
    )
      return null;
    switch (p.operation) {
      case "granted":
        return p.remaining === 1 && !p.expired ? p : null;
      case "accepted":
        return p.remaining === 0 && !p.expired && validWallText(p.text) ? p : null;
      case "rejected":
        return p.remaining === 1 && !p.expired ? p : null;
      case "revoked":
        return !p.expired ? p : null;
      case "expired":
        return p.expired ? p : null;
      default:
        return null;
    }
  } catch {
    return null;
  }
}

export function readWallNoteData(value: unknown): {
  instanceId: string;
  source: { kind: "wall_event"; eventId: "awa_wall_notes_v1"; day: 1 };
  remaining: 0 | 1;
  expired: boolean;
} | null {
  try {
    const p = copyEventData(value) as any;
    if (
      !p ||
      Array.isArray(p) ||
      Object.keys(p).length !== 4 ||
      !Object.keys(p).every((k) => ["instanceId", "source", "remaining", "expired"].includes(k)) ||
      typeof p.instanceId !== "string" ||
      !/^wall:1:[1-9][0-9]*$/.test(p.instanceId) ||
      ![0, 1].includes(p.remaining) ||
      typeof p.expired !== "boolean" ||
      !p.source ||
      Array.isArray(p.source) ||
      Object.keys(p.source).length !== 3 ||
      p.source.kind !== "wall_event" ||
      p.source.eventId !== "awa_wall_notes_v1" ||
      p.source.day !== 1
    )
      return null;
    return p;
  } catch {
    return null;
  }
}

/**
 * 黯月独立 history 的严格读取、纯选择与原私有状态投影。共享政策和 scalar reader 来自
 * state-data，数组与吞噬 history 的完整校验仍在此处；本模块不写 live 能力或借用 lease。
 * 明辉庇护的数据已归独立 owner，不能借迁移合并两种状态的验证或付款规则。
 */
import type { RoleComponent } from "../../../../core/domain/components/role";

import { types } from "node:util";
import { RADIANT_ECLIPSE_POLICY, record, positive } from "./state-data";
export { RADIANT_ECLIPSE_POLICY } from "./state-data";

const goodRoles = ["villager", "seer", "witch", "dreamer", "radiant_count"] as const;
export type EclipseSwallowedRole = (typeof goodRoles)[number];
export interface EclipseState {
  policy: typeof RADIANT_ECLIPSE_POLICY;
  history: Array<{
    day: number;
    targetId: number | null;
    roleId: EclipseSwallowedRole | null;
    abilityId: string | null;
  }>;
}

function items(value: unknown): unknown[] | undefined {
  if (types.isProxy(value) || !Array.isArray(value)) return;
  const fields: Record<string, PropertyDescriptor> = Object.getOwnPropertyDescriptors(
    value as object,
  );
  const length: unknown = fields.length?.value;
  if (
    typeof length !== "number" ||
    !Number.isSafeInteger(length) ||
    length < 0 ||
    Reflect.ownKeys(fields).length !== length + 1
  )
    return;
  const out: unknown[] = [];
  for (let index = 0; index < length; index++) {
    const field = fields[String(index)];
    if (!field || !("value" in field)) return;
    out.push(field.value);
  }
  return out;
}

export const createEclipseState = (): EclipseState => ({
  policy: RADIANT_ECLIPSE_POLICY,
  history: [],
});

export function readEclipseState(value: unknown): EclipseState | undefined {
  const current = record(value, ["policy", "history"]);
  if (!current || current.policy !== RADIANT_ECLIPSE_POLICY) return;
  const entries = items(current.history);
  if (!entries) return;
  const history: EclipseState["history"] = [];
  let previous: EclipseState["history"][number] | undefined;
  for (const entry of entries) {
    const choice = record(entry, ["day", "targetId", "roleId", "abilityId"]);
    if (
      !choice ||
      !positive(choice.day) ||
      choice.day < 2 ||
      (previous && choice.day <= previous.day) ||
      (choice.targetId !== null && !positive(choice.targetId))
    )
      return;
    if (choice.targetId === null) {
      if (choice.roleId !== null || choice.abilityId !== null) return;
    } else {
      if (!(goodRoles as readonly unknown[]).includes(choice.roleId)) return;
      if (
        choice.roleId === "villager"
          ? choice.abilityId !== null
          : choice.abilityId !== `copy:eclipse:night:${choice.day}`
      )
        return;
      if (previous?.day === choice.day - 1 && previous.targetId === choice.targetId) return;
    }
    previous = {
      day: choice.day,
      targetId: choice.targetId as number | null,
      roleId: choice.roleId as EclipseSwallowedRole | null,
      abilityId: choice.abilityId as string | null,
    };
    history.push(previous);
  }
  return { policy: RADIANT_ECLIPSE_POLICY, history };
}
export function selectEclipse(
  state: EclipseState,
  day: number,
  targetId: unknown,
  goodIds: readonly number[],
  roleId: unknown,
): EclipseState {
  const current = readEclipseState(state),
    last = current?.history.at(-1);
  if (!current || !positive(day) || day < 2 || (last && day <= last.day))
    throw new Error("eclipse_swallow_unavailable");
  if (targetId === null) {
    if (roleId !== null) throw new Error("eclipse_swallow_target");
  } else if (
    !positive(targetId) ||
    !goodIds.includes(targetId) ||
    !(goodRoles as readonly unknown[]).includes(roleId) ||
    (last?.day === day - 1 && last.targetId === targetId)
  )
    throw new Error("eclipse_swallow_target");
  return {
    policy: RADIANT_ECLIPSE_POLICY,
    history: [
      ...current.history,
      {
        day,
        targetId: targetId as number | null,
        roleId: roleId as EclipseSwallowedRole | null,
        abilityId: targetId === null || roleId === "villager" ? null : `copy:eclipse:night:${day}`,
      },
    ],
  };
}

/** 原 Eclipse 私有槽仍通过既有 reader 投影为独立数据。 */
export function projectEclipseState(role: RoleComponent): EclipseState | undefined {
  return readEclipseState((role.privateState as { readonly eclipse?: unknown }).eclipse);
}

/**
 * 负责明辉／黯月原阵容、吞噬借用租约及已付庇护／反噬效果的唯一权限。
 * 输入为当前能力原体和目标租约；输出为当次资格检查、封存夜效果与关闭事实。
 * 仅原匹配来源可以付款，借用关闭不恢复失效原体；payload、租约和原主抑制仍在此持有。
 * 公共 metadata 安装和退役写归共享实例 owner，原库存、抑制解除、生命校验和失败前缀不变。
 * 规则依据：docs/rules/awa-radiant-eclipse-twelve-v1.md。
 */
import { types } from "node:util";
import { COMPONENT } from "../../../../core/domain/components/names";
import { Role, Camp } from "../../../../core/domain/identity";
import type { RoleComponent } from "../../../../core/domain/components/role";
import {
  aliveLifeDescriptor,
  aliveLifeVersion,
  type AliveComponent,
} from "../../../../core/domain/components/alive";
import type { World } from "../../../../core/domain/world";
import type { GameEvent } from "../../../../core/domain/events";
import {
  captureNightLife,
  type NightLifeScope,
  type NightImmunityClaim,
  type NightRadiantBacklash,
} from "../../../../core/domain/night_effects";
import { allNightAbilities, abilityStatus, type NightAbilityReadView } from "../abilities";
import { grantNightAbility, retireBorrowedNightAbility } from "../ability_changes";
import { openEclipseSuppression } from "./suppression";
import { snapshotBorrowedState, type BorrowedKind } from "./borrowed_state";
import { readEclipseState, selectEclipse, type EclipseState } from "./state";
import { readShelterState } from "./shelter-state";

const invalid = Symbol("invalid_radiant_binding");
function own(value: unknown, key: PropertyKey): unknown {
  if (!value || typeof value !== "object" || types.isProxy(value)) return invalid;
  const d = Object.getOwnPropertyDescriptor(value, key);
  return d && "value" in d ? d.value : d ? invalid : undefined;
}
function factoryLife(life: AliveComponent): boolean {
  if (types.isProxy(life)) return false;
  const a = aliveLifeDescriptor(life),
    b = Object.getOwnPropertyDescriptor(life, "alive");
  return (
    !!a &&
    !!b &&
    a.get === b.get &&
    a.set === b.set &&
    a.enumerable === b.enumerable &&
    a.configurable === b.configurable
  );
}
interface Original {
  id: number;
  role: RoleComponent;
  kind: Role;
  camp: Camp;
  privateState: RoleComponent["privateState"];
  identity: unknown;
  identityValues: unknown[];
  life: AliveComponent;
  version: number;
  campComponent: unknown;
  victory: unknown;
  container: unknown;
  native: NightAbilityReadView | undefined;
  nativeId: string | undefined;
  nativeKind: unknown;
  nativeState: unknown;
  nativeSource: unknown;
  nativeMetadata: readonly unknown[];
  nativePolicy: readonly unknown[];
}
interface BorrowLease {
  target: Original;
  native: NightAbilityReadView | undefined;
  borrowed: NightAbilityReadView | undefined;
  borrowedId: string | null;
  suppression: ReturnType<typeof openEclipseSuppression> | undefined;
}
interface Night {
  day: number;
  closed: boolean;
  status: "open" | "committed" | "aborted";
  living: ReadonlySet<number>;
  knife: boolean;
  swallowOpened: boolean;
  swallowed: boolean;
  targetId: number | null;
  lease: BorrowLease | undefined;
  shelters: Array<{
    actorId: number;
    abilityId: string;
    target: NightLifeScope;
    owner: () => boolean;
  }>;
  sourceChecks: Map<number, () => boolean>;
}
interface Board {
  players: ReadonlyMap<number, Original>;
  maidId: number;
  countId: number;
  knownWolves: readonly number[];
  maidState: EclipseState;
  expectedMaid: string;
  allowed: Map<number, Map<string, NightAbilityReadView>>;
  night: Night | null;
}
const boards = new WeakMap<World, Board>();
const nativeKeys = [
  "id",
  "kind",
  "activation",
  "startsOnDay",
  "expiresAfterDay",
  "maxUses",
  "sourceDisclosed",
] as const;
const policyKeys = [
  "policy",
  "targetPolicy",
  "actionPolicy",
  "selfHealRule",
  "knifeVisibility",
  "potionPolicy",
  "protectionPolicy",
] as const;
const identityKeys = ["id", "seat", "name", "sessionId"] as const;
function original(world: World, id: number): Original {
  const role = world.getComponent(id, COMPONENT.Role)!;
  const life = world.getComponent(id, COMPONENT.Alive)!;
  const identity = world.getComponent(id, COMPONENT.Identity);
  if (!role || !life || !factoryLife(life) || !life.alive || aliveLifeVersion(life) === undefined)
    throw new Error("radiant_original_invalid");
  const native = allNightAbilities(role).filter((a) => a.source.kind === "native");
  if (native.length > 1 || allNightAbilities(role).length !== native.length)
    throw new Error("radiant_original_abilities_invalid");
  return {
    id,
    role,
    kind: role.role,
    camp: role.camp,
    privateState: role.privateState,
    identity,
    identityValues: identityKeys.map((k) => own(identity, k)),
    life,
    version: aliveLifeVersion(life)!,
    campComponent: world.getComponent(id, COMPONENT.Camp),
    victory: world.getComponent(id, COMPONENT.Victory),
    container: own(role.privateState, "abilities"),
    native: native[0],
    nativeId: native[0]?.id,
    nativeKind: native[0]?.kind,
    nativeState: native[0]?.state,
    nativeSource: native[0]?.source,
    nativeMetadata: nativeKeys.map((key) => own(native[0], key)),
    nativePolicy: policyKeys.map((key) => own(native[0]?.state, key)),
  };
}
function current(world: World, p: Original, allowDeath = true): boolean {
  if (
    world.getComponent(p.id, COMPONENT.Role) !== p.role ||
    own(p.role, "role") !== p.kind ||
    own(p.role, "camp") !== p.camp ||
    own(p.role, "privateState") !== p.privateState ||
    world.getComponent(p.id, COMPONENT.Identity) !== p.identity ||
    !identityKeys.every((k, i) => own(p.identity, k) === p.identityValues[i]) ||
    world.getComponent(p.id, COMPONENT.Camp) !== p.campComponent ||
    own(p.campComponent, "camp") !== p.camp ||
    world.getComponent(p.id, COMPONENT.Victory) !== p.victory ||
    world.getComponent(p.id, COMPONENT.Alive) !== p.life ||
    !factoryLife(p.life) ||
    own(p.privateState, "abilities") !== p.container
  )
    return false;
  const v = aliveLifeVersion(p.life);
  return p.life.alive ? v === p.version : allowDeath && v === p.version + 1;
}
function requireBoard(world: World): Board {
  const b = boards.get(world);
  if (!b) throw new Error("radiant_board_missing");
  if (
    world.entityIds().length !== b.players.size ||
    [...b.players.values()].some((p) => !current(world, p))
  )
    throw new Error("radiant_roster_revoked");
  for (const p of b.players.values()) {
    originalAbility(p);
    const allowed = b.allowed.get(p.id)!;
    const container = own(p.privateState, "abilities");
    const keys = container === undefined ? [] : Reflect.ownKeys(container as object);
    if (
      keys.length !== allowed.size ||
      keys.some(
        (key) =>
          typeof key !== "string" || !allowed.has(key) || own(container, key) !== allowed.get(key),
      )
    )
      throw new Error("radiant_ability_membership_revoked");
  }
  if (
    own(b.players.get(b.maidId)!.privateState, "eclipse") !== b.maidState ||
    JSON.stringify(readEclipseState(b.maidState)) !== b.expectedMaid
  )
    throw new Error("eclipse_state_revoked");
  return b;
}
function requireNight(world: World, day: number): { b: Board; n: Night } {
  const b = requireBoard(world),
    n = b.night;
  if (!n || n.day !== day || n.closed) throw new Error("radiant_night_unavailable");
  return { b, n };
}
function originalAbility(p: Original): NightAbilityReadView | undefined {
  const a = p.native;
  if (!a) return undefined;
  if (
    own(p.container, p.nativeId!) !== a ||
    own(a, "id") !== p.nativeId ||
    own(a, "kind") !== p.nativeKind ||
    own(a, "state") !== p.nativeState ||
    own(a, "source") !== p.nativeSource ||
    own(p.nativeSource, "kind") !== "native" ||
    own(p.nativeSource, "role") !== p.kind ||
    own(a, "activation") !== undefined ||
    !nativeKeys.every((key, i) => own(a, key) === p.nativeMetadata[i]) ||
    !policyKeys.every((key, i) => own(p.nativeState, key) === p.nativePolicy[i])
  )
    throw new Error("radiant_original_ability_revoked");
  return a;
}
function stateGuard(a: NightAbilityReadView): () => boolean {
  const state = own(a, "state") as NightAbilityReadView["state"],
    source = own(a, "source") as NightAbilityReadView["source"];
  if (
    !state ||
    !source ||
    types.isProxy(state) ||
    types.isProxy(source) ||
    typeof state !== "object" ||
    typeof source !== "object"
  )
    throw new Error("radiant_ability_state_invalid");
  const fields = [
    "id",
    "kind",
    "activation",
    "startsOnDay",
    "expiresAfterDay",
    "maxUses",
    "uses",
    "lastUsedDay",
    "disabled",
    "deathExpired",
    "sourceDisclosed",
  ] as const;
  const values = fields.map((k) => own(a, k));
  const sourceKeys = ["kind", "role", "actorId", "abilityId"] as const,
    sourceValues = sourceKeys.map((k) => own(source, k));
  const keys = Reflect.ownKeys(state),
    valuesState = keys.map((k) => own(state, k));
  if (values.includes(invalid) || sourceValues.includes(invalid) || valuesState.includes(invalid))
    throw new Error("radiant_ability_state_invalid");
  const arrays = valuesState.filter(Array.isArray).map((array) => {
    if (types.isProxy(array)) throw new Error("radiant_ability_state_invalid");
    return { array, length: own(array, "length") };
  });
  return () =>
    own(a, "state") === state &&
    own(a, "source") === source &&
    fields.every((k, i) => own(a, k) === values[i]) &&
    sourceKeys.every((k, i) => own(source, k) === sourceValues[i]) &&
    Reflect.ownKeys(state).length === keys.length &&
    keys.every((k, i) => own(state, k) === valuesState[i]) &&
    arrays.every(({ array, length }) => own(array, "length") === length);
